head.script:
// 테스트 설명, 유효성 값 설정
//  ★ _18 : dummy_xlsstyle_rownum (Excel 파일 스타일 옵션 - 행번호 열) 계열 중 행번호 열 표시 옵션과 Header/Body 영역 서식 옵션
//     - rowNumVisible / rowNumHeaderValue / rowNumHeaderColor / rowNumHeaderFontName / rowNumHeaderFontSize / rowNumHeaderFontColor
//       / rowNumBodyColor / rowNumBodyFontName / rowNumBodyFontSize / rowNumBodyFontColor
//     같은 계열의 Footer / SubTotal 영역 서식 옵션 8 개는 _19 에서 다룬다.
//     _15 (Header/Body) / _16 (SubTotal/Footer) / _17 (GroupBy/줄무늬) 과 대칭 구성이며 description 은 분리 샘플 공통(_1 과 동일).
scwin.tData = {
    "description" : "[gridView > M > advancedExcelDownload]<br/>GridView 컴포넌트의 데이터를 Excel 파일로 다운로드합니다.",
    "validation" : [
        "rowNumVisible(선택) 파라미터로 Excel 파일에 행번호를 표시하는 열을 추가할지 'true'/'false' 로 설정합니다.",
        "rowNumVisible(선택) 파라미터값을 'true' 로 설정해도 GridView 가 GroupBy 상태이면 rowNumVisible 파라미터는 무시됩니다.",
        "rowNumVisible(선택) 파라미터를 생략하면 기본값 'false' 가 적용됩니다.",
        "rowNumHeaderValue(선택) 파라미터로 rowNumVisible 파라미터값이 'true' 일때 행번호 열의 Header 에 표시할 값을 설정합니다.",
        "rowNumHeaderValue(선택) 파라미터를 생략하면 기본값 '' 이 적용됩니다.",
        "rowNumHeaderColor(선택) 파라미터로 rowNumVisible 파라미터값이 'true' 일때 행번호 열의 Header 영역 배경색을 설정합니다.",
        "rowNumHeaderColor(선택) 파라미터를 생략하면 기본값 '' 이 적용됩니다.",
        "rowNumHeaderFontName(선택) 파라미터로 rowNumVisible 파라미터값이 'true' 일때 행번호 열의 Header 영역 폰트 이름을 설정합니다.",
        "rowNumHeaderFontName(선택) 파라미터를 생략하면 기본값 '' 이 적용됩니다.",
        "rowNumHeaderFontSize(선택) 파라미터로 rowNumVisible 파라미터값이 'true' 일때 행번호 열의 Header 영역 폰트 크기를 설정합니다.",
        "rowNumHeaderFontSize(선택) 파라미터를 생략하면 기본값 '' 이 적용됩니다.",
        "rowNumHeaderFontColor(선택) 파라미터로 rowNumVisible 파라미터값이 'true' 일때 행번호 열의 Header 영역 폰트 색상을 설정합니다.",
        "rowNumHeaderFontColor(선택) 파라미터를 생략하면 기본값 '' 이 적용됩니다.",
        "rowNumBodyColor(선택) 파라미터로 rowNumVisible 파라미터값이 'true' 일때 행번호 열의 Body 영역 배경색을 설정합니다.",
        "rowNumBodyColor(선택) 파라미터를 생략하면 기본값 '' 이 적용됩니다.",
        "rowNumBodyFontName(선택) 파라미터로 rowNumVisible 파라미터값이 'true' 일때 행번호 열의 Body 영역 폰트 이름을 설정합니다.",
        "rowNumBodyFontName(선택) 파라미터를 생략하면 기본값 '' 이 적용됩니다.",
        "rowNumBodyFontSize(선택) 파라미터로 rowNumVisible 파라미터값이 'true' 일때 행번호 열의 Body 영역 폰트 크기를 설정합니다.",
        "rowNumBodyFontSize(선택) 파라미터를 생략하면 기본값 '' 이 적용됩니다.",
        "rowNumBodyFontColor(선택) 파라미터로 rowNumVisible 파라미터값이 'true' 일때 행번호 열의 Body 영역 폰트 색상을 설정합니다.",
        "rowNumBodyFontColor(선택) 파라미터를 생략하면 기본값 '' 이 적용됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // con 초기값 명시 설정 (정적 select1 은 selectedIndex 가 초기 적용되지 않는다)
    con_groupby.setValue("");

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 : Header 1줄(병합 없음) / Body 6행 의 GridView 를 동적 생성한다.
//  · advancedExcelDownload 는 DataList 바인딩이 전제 조건이므로 dataList 속성을 반드시 설정한다.
//  · 본 계열은 Excel 파일에 추가되는 행번호 열의 Header 영역 / Body 영역 서식만 확인한다.
//  · Body Column 인덱스 0:부서 1:사원명 2:실적건수 3:실적금액
//  · con_groupby 를 적용하면 부서(인덱스 0) 기준 1 Depth GroupBy 상태가 되어
//    rowNumVisible 파라미터가 무시되는지 확인할 수 있다. (Target 재생성 버튼으로 반영)
scwin.comp_init = async function () {
    // 기존 target / DataList 정리
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }

    let bGroupby = (con_groupby.getValue() === "true");

    // 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제]\n- Header 는 1줄(병합 없음), Body Column 인덱스 0 부서 / 1 사원명 / 2 실적건수(number) / 3 실적금액(number), Body Row 는 6행\n- 행번호 열은 GridView 화면에는 없고 rowNumVisible 파라미터로 Excel 파일에만 추가되는 열이다. 추가되면 기존 Column 앞(첫 번째 열 A)에 놓이고 Body 에는 1 부터의 번호가 숫자로 채워진다\n- con_groupby 는 현재 [' + (bGroupby ? '적용' : '미적용') + '] 이다. 적용이면 부서(인덱스 0) 기준 1 Depth GroupBy 상태로 생성되며, 값을 바꾼 뒤에는 Target 재생성 버튼을 눌러야 반영된다\n- useStyle 은 전달하지 않는다. 이 10 개 옵션은 useStyle 없이도 적용된다\n- 파일명 download_xlsstyle_rn, 확장자 xlsx 고정 전달(본 계열 검증 대상 아님)\n[절차]\n1. con_groupby 값을 선택하고 Target 재생성 버튼을 눌러 GridView 를 다시 만든다\n2. par 옵션(rowNumVisible / rowNumHeaderValue / rowNumHeaderColor / rowNumHeaderFontName / rowNumHeaderFontSize / rowNumHeaderFontColor / rowNumBodyColor / rowNumBodyFontName / rowNumBodyFontSize / rowNumBodyFontColor) 값을 선택한다\n3. advancedExcelDownload 버튼을 클릭해 Excel 파일을 내려받는다\n[확인]\n- rowNumVisible : true 로 설정하면 Excel 파일 첫 번째 열에 행번호 열이 추가되고 Body 행마다 1 부터의 번호가 채워지는지. false 로 설정하거나 미설정이면 행번호 열이 추가되지 않는지\n- rowNumVisible : con_groupby 를 적용한 상태에서는 true 로 설정해도 행번호 열이 추가되지 않는지. 결과창의 서버 전달값에서도 rowNumVisible 이 false 로 나가는지 함께 확인한다\n- rowNumHeaderValue : 설정한 값(No)이 행번호 열 Header 셀에 표시되는지. 미설정이면 Header 셀이 빈 값인지\n- 아래 8 개 서식 옵션은 Cell 값이 아니라 셀 서식만 바꾸므로 값만 봐서는 차이가 보이지 않는다. 내려받은 파일을 Excel 로 열어 행번호 열의 채우기 색 / 글꼴 이름 / 글꼴 크기 / 글꼴 색으로 확인한다\n- 서식 8 개를 모두 미설정하면 행번호 열은 Header 가 회색(#D9D9D9) 채우기, Body 가 흰색 채우기이고 두 영역 모두 Calibri 11 글꼴이다. 각 옵션의 미설정 확인은 이 기본 서식과 대조한다\n- rowNumHeaderColor : 설정한 색(#FF00FF)이 행번호 열 Header 셀의 채우기 색이 되는지\n- rowNumHeaderFontName : 설정한 글꼴 이름(굴림)이 행번호 열 Header 셀에 적용되는지\n- rowNumHeaderFontSize : 설정한 크기(20)가 행번호 열 Header 셀에 적용되는지\n- rowNumHeaderFontColor : 설정한 색(#0000FF)이 행번호 열 Header 셀의 글자색이 되는지\n- rowNumBodyColor : 설정한 색(#FFF2CC)이 행번호 열 Body 셀 전체의 채우기 색이 되는지\n- rowNumBodyFontName : 설정한 글꼴 이름(굴림)이 행번호 열 Body 셀에 적용되는지\n- rowNumBodyFontSize : 설정한 크기(16)가 행번호 열 Body 셀에 적용되는지\n- rowNumBodyFontColor : 설정한 색(#FF0000)이 행번호 열 Body 셀의 글자색이 되는지\n- 폰트 옵션(FontName / FontSize / FontColor) 중 하나만 설정해도 그 영역 글꼴이 새로 만들어져 기본 글꼴에 있던 글자색 지정이 사라진다. 그래서 기본값과 같은 값(글꼴 크기 11)을 명시해도 미설정과 완전히 같은 파일이 되지는 않는다\n- Header 영역 옵션(4개)과 Body 영역 옵션(4개)은 서로 독립이다. 한쪽만 설정하면 다른 쪽은 기본 서식으로 남는지 함께 확인한다\n- 행번호 열 서식 옵션은 행번호 열에만 적용된다. 기존 4 개 Column 의 Header / Body 서식은 그대로인지 함께 확인한다\n- 결과창의 서버 전달값으로 실제 서버에 전송된 옵션 원문을 함께 확인한다. 서식 8 개는 rowNumVisible 이 true 일 때만 요청에 담기므로, false 이거나 미설정이면 값을 설정해도 미전달로 나온다"', '', 'label1');

    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();

    // 바인딩 DataList
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="dept" name="dept" dataType="text"></w2:column>';
    strDlt += '<w2:column id="empName" name="empName" dataType="text"></w2:column>';
    strDlt += '<w2:column id="saleCnt" name="saleCnt" dataType="number"></w2:column>';
    strDlt += '<w2:column id="saleAmt" name="saleAmt" dataType="number"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    // 부서 3그룹 x 2명 의 6행 데이터
    let jsonData = [
        { "dept" : "영업기획팀", "empName" : "김도현", "saleCnt" : 24, "saleAmt" : 18450000 },
        { "dept" : "영업기획팀", "empName" : "박서연", "saleCnt" : 17, "saleAmt" : 12300000 },
        { "dept" : "고객지원팀", "empName" : "최민아", "saleCnt" : 9,  "saleAmt" : 6450000 },
        { "dept" : "고객지원팀", "empName" : "정우진", "saleCnt" : 21, "saleAmt" : 15200000 },
        { "dept" : "품질관리팀", "empName" : "오세훈", "saleCnt" : 12, "saleAmt" : 8300000 },
        { "dept" : "품질관리팀", "empName" : "윤나래", "saleCnt" : 19, "saleAmt" : 13600000 }
    ];
    dlt_bind.setJSON(jsonData, false);

    // target 생성 (DataList 바인딩)
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" id="" style="width:700px;height:300px;">';
    strTarget += '<w2:caption style="" id="caption1" value="advancedExcelDownload (Excel 파일 스타일 옵션 - 행번호 열의 표시 / Header / Body) 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="180" style="" inputType="text" id="hcol1" value="부서"></w2:column>';
    strTarget += '<w2:column width="150" style="" inputType="text" id="hcol2" value="사원명"></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="hcol3" value="실적건수"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol4" value="실적금액"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="180" style="" inputType="text" id="dept" dataList="dept"></w2:column>';
    strTarget += '<w2:column width="150" style="" inputType="text" id="empName" dataList="empName"></w2:column>';
    strTarget += '<w2:column width="130" style="text-align:right;" inputType="text" dataType="number" id="saleCnt" dataList="saleCnt"></w2:column>';
    strTarget += '<w2:column width="*" style="text-align:right;" inputType="text" dataType="number" displayFormat="#,##0" id="saleAmt" dataList="saleAmt"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // con_groupby 적용 시 부서(인덱스 0) 기준 1 Depth GroupBy 상태로 만든다.
    //  · groupbyHeader / groupbyFooter 를 주지 않으면 빈 Row 가 표시되므로 반드시 설정한다.
    if (bGroupby) {
        target1.groupby({
            sortIndex : [0],
            sortOrder : [1],
            groupbyHeader : [
                { inputType : "toggleButton", depthVisible : true, colSpan : 2, align : "left" },
                { inputType : "expression", expression : "sum('saleCnt')", align : "right" },
                { inputType : "expression", expression : "sum('saleAmt')", align : "right" }
            ],
            groupbyFooter : [
                { colSpan : 2, value : "그룹 소계", align : "right" },
                { inputType : "expression", expression : "sum('saleCnt')", align : "right" },
                { inputType : "expression", expression : "sum('saleAmt')", align : "right" }
            ]
        });
    }
}



// par 옵션값으로 advancedExcelDownload options 객체를 구성한다.
//  · 선택(필수여부 N) 파라미터는 미설정(빈값) 이면 객체에 담지 않아 생략되도록 한다.
//  · 10 개 파라미터 모두 String 타입이므로 selectbox 값을 그대로 전달한다.
//  · fileName / extension 은 고정값이며 본 계열의 검증 대상이 아니다.
scwin.buildOptions = function () {
    let options = { "fileName" : "download_xlsstyle_rn", "extension" : "xlsx" };
    let arrDesc = [];

    let fnSet = function (sKey, vValue) {
        options[sKey] = vValue;
        arrDesc.push(sKey + "=" + vValue);
    };

    let v;
    v = par_rowNumVisible.getValue();         if (v !== "") fnSet("rowNumVisible", v);
    v = par_rowNumHeaderValue.getValue();     if (v !== "") fnSet("rowNumHeaderValue", v);
    v = par_rowNumHeaderColor.getValue();     if (v !== "") fnSet("rowNumHeaderColor", v);
    v = par_rowNumHeaderFontName.getValue();  if (v !== "") fnSet("rowNumHeaderFontName", v);
    v = par_rowNumHeaderFontSize.getValue();  if (v !== "") fnSet("rowNumHeaderFontSize", v);
    v = par_rowNumHeaderFontColor.getValue(); if (v !== "") fnSet("rowNumHeaderFontColor", v);
    v = par_rowNumBodyColor.getValue();       if (v !== "") fnSet("rowNumBodyColor", v);
    v = par_rowNumBodyFontName.getValue();    if (v !== "") fnSet("rowNumBodyFontName", v);
    v = par_rowNumBodyFontSize.getValue();    if (v !== "") fnSet("rowNumBodyFontSize", v);
    v = par_rowNumBodyFontColor.getValue();   if (v !== "") fnSet("rowNumBodyFontColor", v);

    return { "options" : options, "desc" : ((arrDesc.length === 0) ? "{} (rowNumVisible / rowNumHeaderValue / rowNumHeaderColor / rowNumHeaderFontName / rowNumHeaderFontSize / rowNumHeaderFontColor / rowNumBodyColor / rowNumBodyFontName / rowNumBodyFontSize / rowNumBodyFontColor 전체 생략)" : arrDesc.join(" / ")) };
}



// 다운로드 요청 캡처 : 다운로드는 숨겨진 iframe 으로 form 전송되며 form 은 전송 직후 제거되므로,
//  메소드 호출 구간에서만 form submit 을 감싸 서버로 실제 전달되는 값을 읽고 곧바로 원복한다. (실제 요청은 그대로 통과)
scwin.hookRequest = function () {
    scwin.gVar = { "body" : "" };

    let fnSubmit = HTMLFormElement.prototype.submit;
    HTMLFormElement.prototype.submit = function () {
        if (scwin.gVar.body === "") {
            let objInput = this.querySelector("input[name=xmlValue]");
            scwin.gVar.body = (objInput === null) ? "" : objInput.value;
        }
        return fnSubmit.apply(this, arguments);
    };

    scwin.gVar.unhook = function () {
        HTMLFormElement.prototype.submit = fnSubmit;
    };
}



// 캡처한 요청 본문에서 서버로 전달된 옵션값을 읽는다. (전달되지 않은 옵션은 미전달로 표시)
//  · 이 계열 10 개는 파라미터명과 전송 키가 같다.
//  · 서식 8 개는 rowNumVisible 이 true 로 확정된 경우에만 요청에 담기므로,
//    false / 미설정이거나 GroupBy 상태이면 값을 설정해도 미전달로 나온다.
scwin.getSentValue = function (sParamName) {
    let sBody = scwin.gVar.body || "";
    let nKey = sBody.indexOf("hashkey='" + sParamName + "'");
    if (nKey < 0) return "(미전달)";

    let sRest = sBody.substring(nKey);
    let nVal = sRest.indexOf("value='");
    if (nVal < 0) return "(미전달)";

    sRest = sRest.substring(nVal + 7);
    return sRest.substring(0, sRest.indexOf("'"));
}



// advancedExcelDownload 실행
scwin.btn_advancedExcelDownload_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    let objBuild = scwin.buildOptions();

    scwin.hookRequest();
    try {
        target1.advancedExcelDownload(objBuild.options);
    } finally {
        scwin.gVar.unhook();
    }

    bottom.setReturnValue("전달 옵션 : " + objBuild.desc);
    bottom.setReturnValue("서버 전달값(표시) : rowNumVisible=" + scwin.getSentValue("rowNumVisible") + " / rowNumHeaderValue=" + scwin.getSentValue("rowNumHeaderValue"));
    bottom.setReturnValue("서버 전달값(Header) : rowNumHeaderColor=" + scwin.getSentValue("rowNumHeaderColor") + " / rowNumHeaderFontName=" + scwin.getSentValue("rowNumHeaderFontName") + " / rowNumHeaderFontSize=" + scwin.getSentValue("rowNumHeaderFontSize") + " / rowNumHeaderFontColor=" + scwin.getSentValue("rowNumHeaderFontColor"));
    bottom.setReturnValue("서버 전달값(Body) : rowNumBodyColor=" + scwin.getSentValue("rowNumBodyColor") + " / rowNumBodyFontName=" + scwin.getSentValue("rowNumBodyFontName") + " / rowNumBodyFontSize=" + scwin.getSentValue("rowNumBodyFontSize") + " / rowNumBodyFontColor=" + scwin.getSentValue("rowNumBodyFontColor"));
}
